<?phpadd_action( 'add_meta_boxes', 'myplugin_add_custom_box' );function myplugin_add_custom_box() {	add_meta_box( 'metabox-product', 'برگه نمایش', 'custom_box_product', 'post', 'normal', 'high' );}function custom_box_product( $post ) {	$values = get_post_custom($post->ID);	$filetype = $values["filetype_field"][0];		wp_nonce_field( 'product_nonce', 'product_meta_box_nonce' );	?>		یک برگه متناسب با محتوای خود جهت نمایش انتخاب نمایید<p>     <select style="width:30%;" name="filetype_field" id="filetype_field" class="postbox">		<option value="default" <?php if( $filetype == 'default' || $filetype == '' ) { ?>selected="selected"<?php } ?>>برگه پیش فرض</option>		<option value="video" <?php if( $filetype == 'video' ) { ?>selected="selected"<?php } ?>>برگه نمایش ویدئو</option>		<option value="volume" <?php if( $filetype == 'volume' ) { ?>selected="selected"<?php } ?>>برگه نمایش صوت</option>        <option value="images" <?php if( $filetype == 'images' ) { ?>selected="selected"<?php } ?>>برگه گالری تصاویر</option>        <option value="newspaper" <?php if( $filetype == 'newspaper' ) { ?>selected="selected"<?php } ?>>برگه گیشه روزنامه</option>		<option value="frown" <?php if( $filetype == 'frown' ) { ?>selected="selected"<?php } ?>>برگه گرافیک</option>		<option value="spical" <?php if( $filetype == 'spical' ) { ?>selected="selected"<?php } ?>>برگه ویژه های خبری</option>    </select></p><?php }add_action( 'save_post', 'metabox_save_postdata' );function metabox_save_postdata( $post_id ) {		if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;		if( !isset( $_POST['product_meta_box_nonce'] ) || !wp_verify_nonce( $_POST['product_meta_box_nonce'], 'product_nonce' ) ) return;		    if ( array_key_exists('filetype_field', $_POST ) ) {        update_post_meta( $post_id,'filetype_field', $_POST['filetype_field'] );    }}?>